jQuery(function () {
    // Custom validator to ensure at least one checkbox is checked unless superadmin
    jQuery.validator.addMethod(
        "permissionsRequired",
        function (value, element) {
            var roleName = $.trim($("#role_name").val()).toLowerCase();
            if (roleName === "superadmin") return true;

            return (
                $("input[name='permissions[]']").length > 0 &&
                $("input[name='permissions[]']:checked").length > 0
            );
        },
        "Please select at least one permission."
    );

    $(".js-validation-role").validate({
        rules: {
            role_name: {
                required: true,
                maxlength: 30,
            },
            "permissions[]": {
                permissionsRequired: true,
            },
        },
        messages: {
            role_name: {
                required: "Please enter a Role name.",
                maxlength: "Role name cannot exceed 30 characters.",
            },
        },
        errorClass: "is-invalid",
        validClass: "is-valid",
        errorElement: "div",
        highlight: function (element) {
            $(element).addClass("is-invalid").removeClass("is-valid");
        },
        unhighlight: function (element) {
            $(element).addClass("is-valid").removeClass("is-invalid");
        },
        errorPlacement: function (error, element) {
            if (element.attr("name") === "permissions[]") {
                // Remove any previous error message
                $("#permission-error").remove();
                // Always insert error just below the assign permissions label
                error
                    .attr("id", "permission-error")
                    .addClass("invalid-feedback d-block");
                $("#assign-permissions-label").after(error);
            } else {
                error.addClass("invalid-feedback");
                element.after(error);
            }
        },
        submitHandler: function (form, event) {
            // Revalidate permissions[] manually
            $("input[name='permissions[]']").valid();

            // Check manually again before final submit
            var roleName = $.trim($("#role_name").val()).toLowerCase();
            var checkedCount = $("input[name='permissions[]']:checked").length;
            if (roleName !== "superadmin" && checkedCount === 0) {
                // Show accordion to make it visible
                $(".accordion-collapse").collapse("show");

                // Prevent submission
                return false;
            }

            form.submit();
        },
        invalidHandler: function (_, validator) {
            if (validator.errorList.length) {
                $(validator.errorList[0].element).trigger("focus");
            }
        },
    });

    // Re-validate permissions when role name is changed
    $("#role_name").on("input", function () {
        $("input[name='permissions[]']").valid();
    });
});
